/**
 * Shared types module contract (WS scaffold).
 *
 * Lanes: do NOT edit this file. Add your own types in your own file
 * (e.g. workspace/lib/types.arm.ts) and import/re-export from there.
 * Types here are the minimal cross-lane vocabulary; extend, never mutate.
 */

/** Generic API envelope for all smalt emulator responses. */
export interface SmaltResponse<T> {
  status: number;
  data: T | null;
  error?: { code: string; message: string };
}

/** Lifecycle state for any provisioned resource shown in the console. */
export type ResourceState =
  | "pending"
  | "provisioning"
  | "succeeded"
  | "failed"
  | "canceled";

export interface SmaltResource {
  id: string;
  name: string;
  type: string;
  location: string;
  state: ResourceState;
  tags?: Record<string, string>;
}

/** Copilot proposal — the console is zero-actuation: proposals only. */
export interface CopilotProposal {
  id: string;
  summary: string;
  targetResourceId?: string;
  createdAt: string;
  /** Always false in this console; execution is out of scope by design. */
  executed: false;
}

/** Connection status for the Web Serial hardware bridge. */
export type SerialBridgeStatus =
  | "unsupported"
  | "disconnected"
  | "connecting"
  | "connected"
  | "error";

/** AtomVM wasm module lifecycle. */
export type WasmModuleState = "not-loaded" | "loading" | "running" | "faulted";
